import{_ as a,o as r,c as t,a2 as i}from"./chunks/framework.LJP3gfxI.js";const p=JSON.parse('{"title":"SQLiteMigrationSet — takoform_sqlite_migration_set","description":"","frontmatter":{},"headers":[],"relativePath":"proposals/edge/sqlite-migration-set.md","filePath":"proposals/edge/sqlite-migration-set.md"}'),o={name:"proposals/edge/sqlite-migration-set.md"};function s(n,e,d,l,c,h){return r(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="sqlitemigrationset-—-takoform-sqlite-migration-set" tabindex="-1">SQLiteMigrationSet — <code>takoform_sqlite_migration_set</code> <a class="header-anchor" href="#sqlitemigrationset-—-takoform-sqlite-migration-set" aria-label="Permalink to &quot;SQLiteMigrationSet — `takoform_sqlite_migration_set`&quot;">​</a></h1><h2 id="workload-and-consumer" tabindex="-1">Workload and consumer <a class="header-anchor" href="#workload-and-consumer" aria-label="Permalink to &quot;Workload and consumer&quot;">​</a></h2><p>An application records an ordered, reviewable sequence of SQL files that moves one SQLite database forward.</p><h2 id="role" tabindex="-1">Role <a class="header-anchor" href="#role" aria-label="Permalink to &quot;Role&quot;">​</a></h2><p><code>revision</code>. The whole desired state is one committed <code>manifestDigest</code>; any change to a migration path, digest, or order is a new set.</p><h2 id="observable-semantics" tabindex="-1">Observable semantics <a class="header-anchor" href="#observable-semantics" aria-label="Permalink to &quot;Observable semantics&quot;">​</a></h2><p>The referenced artifact manifest has kind <code>MigrationBundle</code>. It carries an ordered non-empty <code>files</code> list, every entry uses <code>application/sql</code>, and it carries no module members. Order is semantic migration order. SQL bytes live in the content-addressed blob store and never in Form desired state or provider state (<a href="./../../spec/decisions/0033-edge-app-assets-and-sqlite-migrations-are-content-addressed.html">decision 0033</a>).</p><h2 id="why-this-is-one-form" tabindex="-1">Why this is one Form <a class="header-anchor" href="#why-this-is-one-form" aria-label="Permalink to &quot;Why this is one Form&quot;">​</a></h2><p>The sequence is reviewed and applied as one immutable history target. Separate file resources would make ordering an external convention and admit a partially declared set.</p><h2 id="what-would-require-a-separate-form" tabindex="-1">What would require a separate Form <a class="header-anchor" href="#what-would-require-a-separate-form" aria-label="Permalink to &quot;What would require a separate Form&quot;">​</a></h2><p>Another database dialect, reversible migration language, or schema declarator is a different contract rather than another field.</p><h2 id="provided-interfaces" tabindex="-1">Provided Interfaces <a class="header-anchor" href="#provided-interfaces" aria-label="Permalink to &quot;Provided Interfaces&quot;">​</a></h2><p>None.</p><h2 id="accepted-bindings" tabindex="-1">Accepted Bindings <a class="header-anchor" href="#accepted-bindings" aria-label="Permalink to &quot;Accepted Bindings&quot;">​</a></h2><p>None.</p><h2 id="lifecycle-risks" tabindex="-1">Lifecycle risks <a class="header-anchor" href="#lifecycle-risks" aria-label="Permalink to &quot;Lifecycle risks&quot;">​</a></h2><p>Rewriting an applied file is not an update; the application refuses any set whose ordered path+digest sequence no longer extends the database ledger. Deleting the set is blocked while an application references it.</p><h2 id="prior-art" tabindex="-1">Prior art <a class="header-anchor" href="#prior-art" aria-label="Permalink to &quot;Prior art&quot;">​</a></h2><p>Ordered file-based SQLite migration bundles with checksum history, made content-addressed so a filename alone can never hide changed SQL.</p>',19)])])}const f=a(o,[["render",s]]);export{p as __pageData,f as default};
